def gauss_jordan_solve(A, b, n):
    """Solve A x = b by Gauss-Jordan with partial pivoting.
    A is the factor correlation matrix (unit diagonal), so the pivot is the share
    of a factor's variance not explained by the factors eliminated before it.
    Returns (False, None) when a pivot falls below FN_PIVOT_TOL."""
    aug = [[A[i][j] for j in range(n)] + [b[i]] for i in range(n)]
    for col in range(n):
        pivot_row = col
        pivot_val = abs(aug[col][col])
        for r in range(col + 1, n):
            if abs(aug[r][col]) > pivot_val:
                pivot_val = abs(aug[r][col])
                pivot_row = r
        if pivot_val < FN_PIVOT_TOL:
            return False, None
        if pivot_row != col:
            aug[col], aug[pivot_row] = aug[pivot_row], aug[col]
        pivot = aug[col][col]
        for c in range(n + 1):
            aug[col][c] /= pivot
        for r in range(n):
            if r == col:
                continue
            f = aug[r][col]
            if f == 0.0:
                continue
            for c in range(n + 1):
                aug[r][c] -= f * aug[col][c]
    return True, [aug[i][n] for i in range(n)]
